-- =====================================================================
-- 20260603120000_mapa_import_osg.sql
-- Importa os dados históricos do MAPA (HERMES_OSG/mapeamento/export) para
-- o schema Lovable (Supabase / PostgreSQL).
--
-- Origem: SQLite (TEXT IDs slug) → Destino: Postgres (UUID IDs).
-- IDs traduzidos via mapa_uuid(slug) = md5('mapa-osg:' || slug)::uuid.
--
-- Idempotente: ON CONFLICT DO NOTHING em todos os INSERTs.
-- Envelopado em BEGIN/COMMIT.
--
-- Conteúdo:
--   1. helper mapa_uuid(text)
--   2. projects                 (6 linhas)
--   3. (job_roles PULADO — vínculos resolvidos via mapa manual de slug→uuid existente)
--   4. documentos_processo      (120 linhas)
--   5. sistemas_processo        (16 linhas)
--   6. gargalos                 (91 linhas)
--   7. processes                (32 linhas)
--   8. process_stages           (167 linhas, AS-IS apenas — TO-BE vazio no export)
--   9. etapa_responsaveis       (169/228 linhas — 59 puladas, ver bloco)
--  10. etapa_sistemas           (219 linhas)
--  11. etapa_documentos         (204 linhas)
--  12. gargalo_processos        (91 linhas)
--  13. sistema_clusters         (16 linhas)
--
-- Tabelas puladas (0 linhas no export ou requisitos NOT NULL incompatíveis):
--   melhorias, melhoria_*, gargalo_responsaveis, sistema_responsaveis,
--   projeto_justificativas, documento_horas_historico, cascata_*,
--   process_snapshots (3 linhas placeholder — process_scenarios exige
--   scenario_kind/varied_field/parameters/created_by NOT NULL; recriar pela UI),
--   job_roles (decisão do usuário: usar cargos existentes via mapa manual).
-- =====================================================================

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE OR REPLACE FUNCTION public.mapa_uuid(slug text) RETURNS uuid
LANGUAGE sql IMMUTABLE AS $$ SELECT md5('mapa-osg:' || slug)::uuid $$;


-- 1. projects (6 linhas)
ON CONFLICT (id) DO NOTHING;

-- 2. job_roles — PULADO. responsavel_id é resolvido contra job_roles existentes:
--    resp-osg-assistente   → Assistente Administrativo (aa77a98a-74a3-438d-af72-d2100beb9763) — 57 vínculos
--    resp-osg-senior       → Analista Fiscal Sr        (1bdb36fd-b65b-4503-aadd-e1b04f505e44) — 99 vínculos
--    resp-osg-back-office  → Assistente Administrativo (aa77a98a-74a3-438d-af72-d2100beb9763) — 5 vínculos
--    resp-osg-gerente      → Gerente                   (aa53bfa1-f8c5-4509-855c-127698caaaef) — 8 vínculos
--    resp-osg-socio        → Coordenador                (9eac2a09-7527-4d6b-ae65-b5004d76cea4) — 8 vínculos
-- PULADOS (vínculos descartados):
--    resp-osg-cliente      — 45 vínculos
--    resp-osg-fiscal       — 6 vínculos
-- Total: 177 / 228 sobrevivem (78%).

-- 3. documentos_processo (120 linhas)
ON CONFLICT (id) DO NOTHING;

-- 4. sistemas_processo (16 linhas)
ON CONFLICT (id) DO NOTHING;

-- 5. gargalos (91 linhas)
ON CONFLICT (id) DO NOTHING;

-- 6. processes (32 linhas)
   order_index, deliverable, evaluation_status, training_hours, mapped_at, created_at, updated_at)
VALUES
  (mapa_uuid('prc-osg-p1-01'), mapa_uuid('prj-osg-p1'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P1.01 Diagnóstico Patrimonial Inicial', 'Levantamento completo do patrimônio do cliente em uma planilha-mestra (DP), feito no início do projeto. Cruza a declaração de IR (valor contábil) com as matrículas (identificação, área, titularidade, ônus) e com CCIR/IPTU (códigos de conferência), faz a leitura ponta a ponta das averbações/registros para detectar impedimentos e classifica cada bem na coluna integraliza (sim / primeiro momento / segundo momento / não). Registra a titularidade por matrícula distinguindo propriedade de fato e propriedade de direito. É o entregável que dispara todo o resto do projeto e serve de checklist do que falta receber do cliente.', '1x por projeto', 'Alta', 'discovery', 1, 'Planilha-mestra DP completa, com titularidade (fato x direito) por matrícula, coluna integraliza classificada (sim / 1o momento / 2o momento / não) e observações referenciando a averbação de cada impedimento', 'Não avaliado', NULL, '2026-06-02T16:09:31.958Z', to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p1-02'), mapa_uuid('prj-osg-p1'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P1.02 Atualização do Diagnóstico Patrimonial', 'Revisão recorrente do DP ao longo do projeto a cada novo documento ou mudança enviada pelo cliente. Ao receber uma matrícula nova ou regularizada, a equipe lê matrícula por matrícula, atualiza área, valor contábil e denominação, reclassifica a coluna integraliza (tipicamente promovendo imóveis de segundo momento) e sinaliza os impactos. É o gatilho da cascata de 5 a 8 alterações contratuais simultâneas no societário. Também é revisitado no encerramento do projeto para consolidar o que foi e o que não foi integralizado.', '6-7x por projeto/ano', 'Alta', 'discovery', 2, 'DP versão N+1 atualizado, com reclassificação da coluna integraliza, sinalização dos impactos cascata nos contratos e, no encerramento, consolidação do que foi e do que não foi integralizado', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p1-03'), mapa_uuid('prj-osg-p1'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P1.03 Digitação de Matrícula', 'Produção do papel de trabalho (WP) de digitação de matrícula, feita pelo back-office (ou assistente quando não há SIGEF). Extrai e transcreve a descrição do imóvel — área, denominação, localização, proprietário, código rural/urbano e, sobretudo, os limites e confrontações precisos — a partir da matrícula em PDF, manualmente ou via busca estruturada no SIGEF. Esse texto alimenta tanto o DP (verificação de área) quanto o preâmbulo dos contratos sociais e os anexos de parceria e composse, onde será copiado caractere por caractere.', '1x por imóvel', 'Alta', 'discovery', 3, 'WP de digitação de matrícula (modelo Word) com limites e confrontações precisos, prontos para serem copiados ao preâmbulo dos contratos e anexos', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-01'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.01 Qualificação dos Sócios (WP Sócios + Capital Social)', 'Produção dos papéis de trabalho que alimentam o preâmbulo e a cláusula de capital de todos os contratos: a Qualificação dos Sócios (dados pessoais completos das PFs) e a Planilha de Capital Social (soma, por sócio, do valor contábil que cada um leva à integralização).', '1x por projeto', 'Média', 'discovery', 1, 'WP Sócios com qualificação completa de cada PF + Planilha Excel de Capital Social somada por sócio', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-02'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.02 Constituição Societária Agro', 'Constituição do primeiro contrato real do projeto: a PJ Agro (operacional, LTDA), que receberá os imóveis. O capital social inicial é a soma do que será integralizado, cotistas são as PFs e o objeto social é fechado em atividade agro/rural para preservar a imunidade de ITBI. Modelo Word com revisão por 3 pessoas e registro na Junta Comercial.', '1x por projeto', 'Alta', 'discovery', 2, 'Contrato Social Agro registrado na Junta Comercial, CNPJ e NIRE ativos', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-03'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.03 Constituição Societária Participações', 'Constituição da PJ Participações, a holding controladora (LTDA) que detém apenas cotas, não imóveis. Cotistas são as PFs no momento da constituição. Objeto social diferente da Agro (gestão de participações), por isso é trabalho distinto, mas elaborada em conjunto e com registro simultâneo na Junta.', '1x por projeto', 'Alta', 'discovery', 3, 'Contrato Social Participações registrado na Junta Comercial, CNPJ e NIRE ativos', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-04'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.04 Constituição de Holdings Individuais', 'Quando o projeto exige isolamento patrimonial por sócio, constitui-se uma holding individual (LTDA) por sócio, acima da Participações. Modelo único de processo: o volume captura quantas holdings há naquele cliente. A estrutura típica MMS (Agro + Participações) não tem holdings; projetos maiores têm 1 por sócio.', '0-N por projeto', 'Média', 'discovery', 4, 'N contratos sociais de holdings individuais registrados na Junta Comercial (0-N, 1 por sócio)', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-05'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.05 Alteração Contratual - Integralização (Agro, cláusula 5ª)', 'Alteração contratual da Agro que efetiva a integralização dos imóveis de 1º momento: aumenta o capital social e lista os imóveis com limites e confrontações na cláusula 5ª. Registrada simultaneamente na Junta com a cessão de cotas (P2.06). Dispara o dever do cliente de atualizar as matrículas no cartório. Frequência sobe na cascata de ACs.', '1x por projeto + N na cascata', 'Alta', 'discovery', 5, 'Alteração Contratual da Agro com cláusula 5ª alterada, registrada na Junta Comercial', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-06'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.06 Alteração Contratual - Cessão de Cotas (concentração na Participações)', 'Alteração contratual que transfere a totalidade das cotas da Agro das PFs para a PJ Participações (concentração de cotas na controladora). É um movimento sem mudança de capital, apenas troca de sócio, refletido na cláusula que trata das quotas/composição societária do contrato da Agro. Registrada simultaneamente com a integralização (P2.05).', '1x por projeto + N na cascata', 'Alta', 'discovery', 6, 'Alteração Contratual com a cessão das cotas da Agro para a Participações (nova composição societária), registrada na Junta', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p2-07'), mapa_uuid('prj-osg-p2'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P2.07 Alteração Contratual - Imóvel Adicional (Agro 2º momento)', 'Alteração contratual adicional na Agro quando um imóvel de 2º momento é finalmente sanado (pendência regularizada pelo cliente) ou quando o cliente adquire novo imóvel durante ou após o projeto. Diferente da P2.05 porque o capital social já existe e apenas aumenta. Recorrente ao longo dos anos, sobrevive ao encerramento oficial do projeto.', '0-N por projeto, recorrente ao longo dos anos', 'Média', 'discovery', 7, 'Alteração Contratual da Agro integralizando imóvel adicional, com novo aumento de capital, registrada na Junta', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p3-01'), mapa_uuid('prj-osg-p3'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P3.01 Planejamento Tributário Rural', 'Estudo tributário da atividade rural executado pela equipe Fiscal (Felipe), que define o percentual da parceria (tipicamente 20/80) e o regime de exploração. A OSG funciona como ponte com o cliente: disponibiliza a planilha gerencial de exploração desde o início do projeto e repassa documentos e dúvidas entre cliente e Fiscal. O resultado é gatilho para finalizar o contrato de parceria.', '1x por projeto', 'Média', 'discovery', 1, 'Relatório do Fiscal definindo o percentual da parceria (20/80 ou outro), o regime de exploração rural e a opção de Funrural, com os cenários tributários', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p3-02'), mapa_uuid('prj-osg-p3'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P3.02 Distrato de Arrendamento Pré-existente', 'Quando o cliente vinha de uma estrutura de arrendamento (caso raro, pois a maioria explora na pessoa física sem arrendamento), é necessário rescindir esse arrendamento antes de configurar a nova relação jurídica via parceria. Elabora-se um contrato de distrato e registra-se em cartório.', '0-N por projeto', 'Média', 'discovery', 2, 'Contrato de distrato do arrendamento pré-existente registrado em cartório', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p3-03'), mapa_uuid('prj-osg-p3'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P3.03 Contrato de Parceria Rural', 'Contrato agrário principal entre a PJ Agro (parceiro-outorgante, dona dos imóveis após a integralização) e as PFs da família (parceiros-outorgados), com base na Lei 4.504/64 (Estatuto da Terra). O percentual é tipicamente 20/80 (terra nua), definido pelo planejamento tributário. Inclui anexo que copia os limites e confrontações da matrícula, troca o proprietário para a PJ, remove o valor contábil e adiciona os hectares efetivamente explorados (planilha preenchida pelo cliente). Elaborado em paralelo aos contratos sociais, mas finalizado após o planejamento tributário e registrado em cartório.', '1x por projeto', 'Alta', 'discovery', 3, 'Contrato de parceria rural registrado em cartório, com anexo (descrição da matrícula + hectares explorados)', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p3-04'), mapa_uuid('prj-osg-p3'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P3.04 Contrato de Composse', 'Contrato complementar entre as pessoas físicas (parceiros-outorgados) que regula como o grupo divide entre si os 80% da parceria. Com base no art. 1.199 do Código Civil, faz remissão ao contrato de parceria como instrumento principal. Na maioria dos casos é pro indiviso (todos exploram tudo, sem demarcar áreas). Quando há área arrendada de terceiros que entra na exploração, ela também é tratada na composse. Elaborado em paralelo aos demais contratos e registrado em cartório.', '1x por projeto', 'Média', 'discovery', 4, 'Contrato de composse registrado em cartório, com anexo (descrição da matrícula + hectares) e remetendo à parceria como instrumento principal', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-01'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.01 Apresentação Inicial de Sucessão', 'Primeira apresentação ao cliente sobre o eixo sucessório, expondo as opções genéricas (doação em vida x testamento, com ou sem holdings) antes de existirem os cálculos de ITCMD. Ocorre quando a estrutura societária ainda está em andamento e nada da doação está definido.', '1x por projeto', 'Média', 'discovery', 1, 'Apresentação ao cliente com opções genéricas de sucessão', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-02'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.02 Planejamento Tributário ITCMD', 'Processo transversal executado pela área Fiscal (Ricardo), que calcula a base do ITCMD sobre as cotas a doar em três cenários (valor contábil, valor de ITR e valor de mercado), para dimensionar o risco de cobrança pela Sefaz. A OSG atua como ponte com o cliente, abrindo a demanda e disponibilizando a planilha de cotas; em paralelo, calcula a divisão da legítima e da parte disponível.', '1x por projeto', 'Alta', 'discovery', 2, 'Relatório de ITCMD com 3 cenários (contábil, ITR, mercado)', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-03'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.03 Apresentação Final de Sucessão', 'Nova apresentação ao cliente, já com a estrutura societária e patrimonial consolidada, resumindo o que foi feito no projeto e expondo os três cenários de ITCMD calculados. O cliente decide se segue ou não com a doação e qual cenário adota como base. Reunião dedicada a essa definição.', '1x por projeto', 'Média', 'discovery', 3, 'Apresentação com cenários de ITCMD para decisão do cliente', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-04'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.04 Recolhimento de ITCMD', 'Após a decisão do cliente, a contabilidade do cliente emite as guias e recolhe o ITCMD. A formalização da doação na Junta só pode ocorrer depois da quitação. A PSA apenas acompanha; o passo pode travar o projeto indefinidamente, inclusive por contestação judicial do imposto.', '1x por projeto', 'Média', 'discovery', 4, 'Guia de ITCMD paga (ou em contestação)', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-05'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.05 Instrumento de Doação de Cotas', 'Elaboração do instrumento de doação das cotas da holding controladora (Participações) dos fundadores para os herdeiros, tipicamente em partes iguais. Inclui cláusulas conforme o desejo da família (cláusulas restritivas, reserva de usufruto). A minuta é disponibilizada ao cliente para análise e aprovação, com reuniões para sanar dúvidas. Só é formalizado após a quitação do ITCMD. Observação de governança: em alguns projetos a doação só ocorre se o Acordo de Quotistas (P5.02) já estiver assinado — o desfecho do projeto fica vinculado a essa pré-condição.', '1x por projeto', 'Média', 'discovery', 5, 'Instrumento de doação de cotas assinado', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-06'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.06 Alteração Contratual - Reflexo da Doação (Participações)', 'Alteração contratual da holding Participações que efetiva a entrega das cotas doadas, fazendo remissão ao instrumento de doação: as cotas que eram do fundador passam ao sucessor. Elaborada de forma conjunta e complementar à doação e registrada na Junta Comercial somente após a quitação do ITCMD.', '1x por projeto', 'Média', 'discovery', 6, 'AC da Participações refletindo a nova composição societária pós-doação, registrada na Junta', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p4-07'), mapa_uuid('prj-osg-p4'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P4.07 Testamento (alternativa à doação)', 'Alternativa quando o cliente prefere não fazer a doação em vida. A PSA elabora a minuta do testamento, disponibiliza ao cliente para aprovação, e leva ao cartório de notas, indicando a lavratura do testamento (documento público que fica na central de cartórios). Fluxo cartorial distinto da doação, sem passar pela Junta Comercial.', '0-1x por projeto', 'Média', 'discovery', 7, 'Testamento lavrado em cartório de notas', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p5-01'), mapa_uuid('prj-osg-p5'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P5.01 Questionário de Governança', 'Diagnóstico de governança familiar: o cliente responde um rol de perguntas padrão que orienta a estruturação da profissionalização da gestão da família. É o gatilho dos demais documentos de governança e começa pela apresentação do projeto de governança ao cliente. Absorve a fase OpenProject Diagnóstico da Governança Familiar. O acompanhamento recorrente (follow-up da governança) ocorre em P6.04.', '1x por projeto', 'Média', 'discovery', 1, 'Respostas do cliente ao questionário de governança consolidadas (diagnóstico de governança familiar)', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p5-02'), mapa_uuid('prj-osg-p5'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P5.02 Acordo de Quotistas', 'Documento Word que disciplina como os sócios decidem entre si (quotas e transferência, eventos pessoais, saída e exclusão, não concorrência, governança e disposições gerais). Menos padronizado que os contratos de P2: parte de um modelo-base e de uma biblioteca de cláusulas, preenchido conforme o cliente responde ao questionário. Pode condicionar a doação do P4 (em alguns projetos só existe doação se o acordo for assinado).', '1x por projeto', 'Alta', 'discovery', 2, 'Acordo de Quotistas assinado', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p5-03'), mapa_uuid('prj-osg-p5'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P5.03 Protocolo de Remuneração', 'Documento que estabelece regras de remuneração e benefícios de sócios e administradores por persona (diretores, sucessores, gestores familiares). Baseia-se em uma planilha Excel checklist de categorias de benefícios e em questionário; o cliente estipula a remuneração conforme o mercado ou o que julga sensato. O documento Word é gerado a partir de um arquivo de referência canônico.', '1x por projeto', 'Alta', 'discovery', 3, 'Protocolo de Remuneração (planilha preenchida + documento Word assinado)', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p5-04'), mapa_uuid('prj-osg-p5'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P5.04 Matriz de Alçadas', 'Planilha que define até onde cada pessoa pode decidir e o que cada nível aprova (por exemplo, um diretor pode executar compra de imóvel até certo valor; acima disso, decide o conselho ou a reunião de sócios). É estrutural mas tem ciclo de aprovação próprio e seu conteúdo reflete no contrato social.', '1x por projeto', 'Média', 'discovery', 4, 'Planilha de matriz de alçadas (quem aprova o que) aprovada', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p5-05'), mapa_uuid('prj-osg-p5'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P5.05 Regimento Interno do Conselho', 'Documento elaborado apenas quando o cliente decide formar conselho de administração (depende do porte do cliente). Diferente dos demais documentos de governança, não parte de um rol de perguntas padrão em branco. Estabelece as regras de funcionamento do conselho.', 'condicional (0-1x por projeto, somente se houver conselho)', 'Média', 'discovery', 5, 'Regimento Interno do Conselho aprovado', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p5-06'), mapa_uuid('prj-osg-p5'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P5.06 Alteração Contratual - Reflexo da Governança (Participações)', 'Alteração do contrato social para formalizar a estrutura de governança quando o cliente forma conselho de administração: ao haver conselho, mexe-se na administração (passa a constar conselho de administração e diretoria), exigindo alterar o contrato social. Registrada na Junta Comercial. Só ocorre se o conselho for formado.', 'condicional (0-1x por projeto, somente se houver conselho)', 'Alta', 'discovery', 6, 'Alteração contratual formalizando conselho/diretoria registrada na Junta Comercial', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p6-01'), mapa_uuid('prj-osg-p6'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P6.01 Solicitações Preliminares', 'Memorando de documentos solicitado ao cliente para abrir o projeto: alinha o escopo com a gerência, dispara a coleta documental e controla o retorno do cliente. Hoje informal (e-mail/WhatsApp), com os documentos do cliente sendo recebidos e guardados no Docbox.', '1x por projeto', 'Baixa', 'discovery', 1, 'Lista de documentos solicitada ao cliente, com checklist de retorno', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p6-02'), mapa_uuid('prj-osg-p6'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P6.02 Entrevista Preliminar / Kickoff', 'Reunião inicial com o cliente para captar expectativas, identificar riscos eminentes do projeto e definir os líderes interno e externo. Também levanta a qualificação inicial dos sócios e a participação societária. Saída alimenta P1, P4 e P5.', '1x por projeto', 'Media', 'discovery', 2, 'Ata de kickoff com expectativas do cliente, riscos eminentes e identificação dos líderes interno/externo', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p6-03'), mapa_uuid('prj-osg-p6'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P6.03 Formalização do Projeto', 'Elaboração do projeto de sucessão empresarial e submissão à aprovação do cliente, com a assinatura do contrato. É o go formal do projeto; sem isso, o trabalho não passa de diagnóstico.', '1x por projeto', 'Media', 'discovery', 3, 'Projeto de sucessão empresarial aprovado pelo cliente e contrato assinado', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p6-04'), mapa_uuid('prj-osg-p6'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P6.04 Acompanhamento e Orientação', 'Gestão recorrente do andamento do projeto: atualização de status com o cliente, controle de prazos, reuniões internas de sprint e orientação das equipes ao longo dos pilares. Captura o overhead de gestão citado como dor de visibilidade.', 'Recorrente ao longo do projeto', 'Media', 'discovery', 4, 'Atualizações de status com o cliente, controle de prazos e reuniões de sprint internas', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prc-osg-p6-05'), mapa_uuid('prj-osg-p6'), '0523512c-f980-4236-8a7c-53e06c9c7a80', 'P6.05 Finalização do Projeto', 'Fechamento do projeto: diagnóstico flash verificando se os objetivos foram alcançados e se há novos riscos, elaboração do relatório final e apresentação/entrega ao cliente (handover).', '1x por projeto', 'Media', 'discovery', 5, 'Diagnóstico flash, relatório final do projeto e entrega ao cliente', 'Não avaliado', NULL, NULL, to_timestamp(1780197035), to_timestamp(1780197035))
ON CONFLICT (id) DO NOTHING;

-- 7. process_stages (167 linhas)
   lead_time_days, volume_per_process, error_rate, rework_rate, error_cost, error_volume,
   stage_order, created_at, updated_at)
VALUES
  (mapa_uuid('etp-osg-p1-01-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Solicitar e coletar documentos do cliente', 'A equipe solicita ao cliente os documentos-base (declaração de IR, matrículas, CCIR, IPTU e, quando a matrícula está desatualizada, escritura ou contrato de compra e venda) e os recebe em PDF via Docbox, pasta interna, e-mail ou WhatsApp. A devolutiva do cliente nesta fase é o maior atraso do processo.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Extrair valor contábil da declaração de IR', 'Abre a declaração de IR (parte de bens e direitos) e extrai apenas o valor contábil de cada bem. A identificação do bem é feita pela denominação (ex.: Casa residencial Dona Eliza, Bandeirantes II lote 08) ou pelo número de matrícula quando consta na descrição.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Extrair dados da matrícula e ler averbações ponta a ponta', 'Lê cada matrícula extraindo tipo de bem, denominação, número, data da certidão, área, proprietário(s). Faz a leitura ponta a ponta (de baixo para cima também) das averbações e registros para identificar impedimentos (hipoteca, penhora, alienação fiduciária, bloqueio judicial, assunção de dívida), verificando até o fim se a averbação foi cancelada. A leitura é manual (olhômetro), apoiada por checklist interno de impedimentos.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Registrar titularidade da matrícula (propriedade de fato x direito)', 'Para cada matrícula, registra quem é o titular distinguindo a propriedade de fato (FT — quem efetivamente detém e explora o imóvel) da propriedade de direito (DT — quem consta como titular registral na matrícula). Quando o titular de fato e o de direito coincidem, a titularidade de direito repete a de fato (copiar da FT). Essa dimensão é central no DP e no cruzamento de titulares, pois define o cliente e direciona a integralização e a futura cessão de cotas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Extrair códigos de CCIR e IPTU para conferência cruzada', 'Extrai apenas o código do CCIR (imóveis rurais) e o código de inscrição do IPTU (imóveis urbanos). Esses códigos servem para confirmar a identidade do imóvel e cruzar matrículas: um mesmo CCIR pode amarrar duas matrículas do mesmo imóvel, caso em que o mesmo código é lançado nas duas linhas do DP.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e6'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Cruzar matrícula x IR e preencher o DP', 'Faz o link entre a matrícula e o valor do IR pela denominação ou número de matrícula (Ctrl+F na declaração, testando o número com e sem ponto/separador). Quando não há remissão direta, vincula pelo nome do imóvel. Preenche a planilha DP com todos os dados (tipo, denominação, matrícula, área, proprietário, códigos, valor contábil) e a observação referenciando a averbação de cada impedimento.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e7'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Tratar matrícula desatualizada integralizando pelos direitos da escritura/CCV', 'Quando a matrícula não está atualizada com o nome de quem é de fato o proprietário (matrícula em nome de terceiro ou de falecido), a equipe não leva a matrícula: integraliza os direitos da escritura pública ou do contrato particular de compra e venda, que fazem remissão à matrícula. O princípio da continuidade impede transferir o que não consta em nome do titular, então o DP registra o bem pelos direitos do instrumento de aquisição com remissão expressa à matrícula de origem.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 7, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-01-e8'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-01'), 'Classificar coluna integraliza e marcar pendências', 'Classifica cada bem na coluna integraliza (sim / primeiro momento / segundo momento / não) conforme os impedimentos identificados. Imóveis com ônus que impede a transferência (penhora, alienação fiduciária, bloqueio) vão para segundo momento até sanar a pendência. Usa o próprio DP como checklist do que falta do cliente: o que está no IR e não tem matrícula e o que tem matrícula e não está no IR.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 8, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-02-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-02'), 'Receber documento novo ou regularizado do cliente', 'Recebe do cliente uma matrícula nova, matrícula com pendência sanada (quitação de ônus), nova área após retificação/georreferenciamento ou valor contábil informado por e-mail, que dispara a atualização do DP.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-02-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-02'), 'Reler matrícula por matrícula e atualizar dados', 'Reabre as matrículas afetadas e relê ponta a ponta, atualizando no DP o tamanho da área, o valor contábil e a denominação que mudaram. Confere os impedimentos novamente para ver se ainda há ônus pendente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-02-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-02'), 'Reclassificar coluna integraliza', 'Reclassifica a coluna integraliza dos imóveis afetados, tipicamente promovendo de segundo momento para sim quando a pendência foi sanada, liberando o imóvel que estava travado para a integralização.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-02-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-02'), 'Sinalizar impactos cascata no societário', 'Identifica que a mudança no DP dispara alterações nos contratos (integralização na Agro, cessão de cotas, holdings individuais). Em estruturas com várias PJs, uma única correção pode disparar 5 a 8 alterações contratuais simultâneas, e a atualização do DP é o gatilho desse trabalho.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-02-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-02'), 'Revisitar o DP no encerramento do projeto', 'Ao encerrar o projeto, a equipe volta ao DP e o atualiza pela última vez para consolidar o que foi e o que não foi integralizado. Pela coluna integraliza filtra para onde foram todos os imóveis (qual alteração contratual recebeu cada bem) e registra quais ficaram de fora e o porquê (impedimento não sanado, pendência do cliente). É o controle final do patrimônio do projeto.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-03-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-03'), 'Obter a matrícula e documentos de descrição', 'Reúne a matrícula atualizada em PDF e, quando aplicável, a matrícula anterior (se a atual fizer remissão), a escritura/CCV se a propriedade ainda não estiver refletida e documentos de georreferenciamento/retificação.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-03-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-03'), 'Obter descrição estruturada via SIGEF (imóvel rural)', 'Quando o imóvel rural está no SIGEF, busca a descrição estruturada do imóvel (limites e confrontações) como alternativa à digitação manual a partir do PDF. Para imóveis urbanos ou sem SIGEF, a etapa é pulada e a descrição é digitada manualmente.', 'hibrido', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-03-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-03'), 'Transcrever descrição e limites/confrontações no WP', 'Preenche o modelo Word de digitação de matrícula com área, denominação, localização, proprietário, matrícula e cartório, código rural/urbano, averbações/registros relevantes e a descrição literal de limites e confrontações. A transcrição dos limites e confrontações é o ponto crítico — um grau que vira um O gera exigência do cartório.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p1-03-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p1-03'), 'Conferir descrição contra o DP e disponibilizar', 'Confere a descrição digitada contra os dados do DP (área, denominação, códigos) e disponibiliza o WP na pasta do projeto, de onde os limites e confrontações serão copiados para o preâmbulo do contrato social e para os anexos de parceria e composse.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-01-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-01'), 'Coletar documentos pessoais dos sócios', 'Recebe do cliente os documentos pessoais das PFs (RG, CPF, CNH, certidões de casamento), por e-mail ou Docbox nos clientes novos. Esses documentos são a fonte da qualificação.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-01-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-01'), 'Preencher a Qualificação dos Sócios (WP Sócios)', 'Extrai dos documentos pessoais os dados de cada sócio (nome, nacionalidade, profissão, estado civil, regime de bens, filiação, número do documento e órgão emissor, endereço) e consolida no papel de trabalho de qualificação usado no preâmbulo dos contratos.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-01-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-01'), 'Montar a Planilha de Capital Social', 'A partir do DP consolidado (imóveis com integraliza = sim/1º momento e respectivo valor contábil do IR), soma por sócio o montante que cada um levará à integralização, definindo o capital social e as cotas. Feita manualmente em Excel.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-01-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-01'), 'Conferir somatório do capital social', 'Confere o somatório do capital social até o centavo, pois diferença por casas decimais entre as planilhas gera erro e, além disso, descasamento entre aporte e cotas recebidas pode ser lido como doação disfarçada (risco de ITCMD).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-02-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-02'), 'Coletar dados de sede, objeto social e administrador', 'Recebe do cliente o endereço de sede, o objeto social pretendido e a definição de quem será o administrador da sociedade Agro.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-02-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-02'), 'Elaborar a minuta do Contrato Social Agro', 'Preenche o modelo Word do contrato social da Agro com a qualificação dos sócios, o capital social vindo da planilha, os imóveis (limites e confrontações da digitação de matrícula) e o objeto agro/rural. Inclui a cláusula 6ª padrão que bloqueia entrada de terceiros.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-02-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-02'), 'Revisar a minuta (checklist + sênior)', 'A minuta passa pelo fluxo de revisão por 3 pessoas: o assistente que executou, o revisor que aplica o checklist e o líder sênior na revisão final. Conferem numeração de cláusulas, capital social, formatação, dados pessoais, endereço e descrição de imóveis.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-02-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-02'), 'Disponibilizar minuta e colher assinaturas do cliente', 'Disponibiliza e salva a minuta aprovada para o cliente analisar e assinar. A assinatura é feita pelo cliente via gov.br/certificado digital. Eventuais discussões de cláusula com o cliente podem atrasar a etapa.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-02-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-02'), 'Registrar o Contrato Social na Junta Comercial', 'Protocola e registra o contrato social da Agro na Junta Comercial, obtendo CNPJ e NIRE. É a etapa final que constitui juridicamente a sociedade e gera os dados da PJ usados como insumo dos instrumentos agrários (P3).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-03-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-03'), 'Elaborar a minuta do Contrato Social Participações', 'Preenche o modelo Word do contrato social da Participações com a qualificação dos sócios, a sede e o administrador, objeto social de gestão de participações (sem imóveis). Inclui a cláusula 6ª padrão que bloqueia terceiros.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-03-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-03'), 'Revisar a minuta (checklist + sênior)', 'A minuta passa pelo fluxo de revisão por 3 pessoas (assistente que executa, revisor com checklist, líder sênior). Conferem numeração de cláusulas, dados pessoais, formatação e objeto social.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-03-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-03'), 'Disponibilizar minuta e colher assinaturas do cliente', 'Disponibiliza e salva a minuta aprovada para o cliente analisar e assinar, normalmente em conjunto com o contrato da Agro. A assinatura é feita pelo cliente via gov.br/certificado digital.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-03-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-03'), 'Registrar o Contrato Social na Junta Comercial', 'Registra o contrato social da Participações na Junta Comercial, de forma simultânea ao da Agro (no mesmo dia, um após o outro), obtendo CNPJ e NIRE. Gera os dados da PJ usados como insumo dos instrumentos agrários (P3).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-04-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-04'), 'Elaborar a minuta da holding individual', 'Para cada sócio que precisa de isolamento patrimonial, preenche o modelo Word de contrato social da holding individual com a qualificação do sócio, sede, administrador e cláusula 6ª padrão de bloqueio de terceiros.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-04-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-04'), 'Revisar a minuta (checklist + sênior)', 'A minuta de cada holding passa pelo fluxo de revisão por 3 pessoas (assistente, revisor com checklist, sênior).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-04-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-04'), 'Colher assinaturas e registrar na Junta Comercial', 'Disponibiliza e salva a minuta para o sócio assinar (assinatura via gov.br/certificado digital) e registra cada holding individual na Junta Comercial, obtendo CNPJ e NIRE.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-05-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-05'), 'Consolidar imóveis de 1º momento a integralizar', 'A partir do DP, seleciona os imóveis classificados como integraliza = sim / 1º momento e o respectivo valor contábil, aguardando consolidar a maior parte do patrimônio antes de integralizar.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-05-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-05'), 'Elaborar a minuta da alteração (cláusula 5ª)', 'Preenche o modelo Word da alteração contratual da Agro alterando a cláusula 5ª: novo capital social (aumento) e lista dos imóveis integralizados com limites e confrontações copiados da digitação de matrícula.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-05-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-05'), 'Revisar a minuta (checklist + sênior)', 'A minuta passa pelo fluxo de revisão por 3 pessoas, com atenção especial à conferência número a número da descrição de área, limites e confrontações e ao novo capital social.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-05-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-05'), 'Colher assinaturas e registrar na Junta (simultâneo com a cessão)', 'Disponibiliza e salva a minuta para o cliente assinar (assinatura via gov.br/certificado digital) e registra a alteração na Junta Comercial, de forma simultânea ao registro da cessão de cotas (P2.06).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-05-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-05'), 'Registrar a integralização nas matrículas e orientar o cliente', 'Faz o registro da integralização na matrícula e orienta o cliente sobre a atualização das matrículas no cartório (responsabilidade do cliente, com custo de ITBI), que pode levar 1 a 2 anos ou ser feita imóvel a imóvel.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 8, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-06-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-06'), 'Verificar balanço e analisar lucros (decisão de ata)', 'Pré-requisito da cessão: a equipe verifica se o cliente disponibilizou o balanço e a equipe fiscal analisa os lucros para decidir se há necessidade de ata antes de concentrar as cotas. Essa verificação pode travar a etapa até que balanço e análise estejam concluídos (relato da reunião de 14/05).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-06-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-06'), 'Elaborar a minuta da cessão de cotas', 'Preenche o modelo Word da alteração contratual que cede 100% das cotas da Agro detidas pelas PFs para a PJ Participações, sem alterar o capital social, refletindo a nova composição societária na cláusula que trata das quotas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-06-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-06'), 'Revisar a minuta (checklist + sênior)', 'A minuta passa pelo fluxo de revisão por 3 pessoas, conferindo a contemplação de cotas e a nova composição societária.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-06-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-06'), 'Colher assinaturas e registrar na Junta (simultâneo com a integralização)', 'Disponibiliza e salva a minuta para o cliente assinar (assinatura via gov.br/certificado digital) e registra a cessão de cotas na Junta Comercial, simultaneamente ao registro da integralização da Agro (P2.05).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-07-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-07'), 'Receber aviso do cliente e matrícula atualizada do imóvel', 'O cliente avisa que a pendência do imóvel de 2º momento foi sanada (ou que comprou novo imóvel) e envia a matrícula atualizada, por e-mail ou Docbox, reabrindo o DP para aquele imóvel.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-07-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-07'), 'Receber a digitação de matrícula do imóvel adicional (insumo de P1.03)', 'A digitação de matrícula (limites e confrontações) é executada pelo Back-office em P1.03 - Digitação de Matrícula. Aqui o WP de digitação é recebido/reutilizado como insumo da minuta, sem refazer a digitação em P2 (evita duplicar o trabalho de P1).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-07-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-07'), 'Elaborar a minuta da alteração (novo aumento de capital)', 'Preenche o modelo Word da alteração contratual da Agro integralizando o imóvel adicional, com novo aumento sobre o capital social já existente e a descrição do imóvel copiada do WP de digitação de matrícula.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-07-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-07'), 'Revisar a minuta (checklist + sênior)', 'A minuta passa pelo fluxo de revisão por 3 pessoas, conferindo a descrição do imóvel adicional e o novo valor do capital social.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p2-07-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p2-07'), 'Colher assinaturas e registrar na Junta Comercial', 'Disponibiliza e salva a minuta para o cliente assinar (assinatura via gov.br/certificado digital) e registra a alteração na Junta Comercial, atualizando o capital social já registrado da Agro.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-01-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-01'), 'Disponibilizar planilha de exploração ao cliente', 'A OSG envia ao cliente, desde o início do projeto, a planilha gerencial padrão de exploração/cotas para que ele preencha as informações da atividade rural (produtos, área explorada, fluxo de comercialização).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-01-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-01'), 'Abrir demanda de planejamento tributário ao Fiscal e reunir documentos de entrada', 'Com o DP aprovado, a OSG abre a demanda de planejamento tributário para a equipe Fiscal e repassa os dados do cliente. O Fiscal possui sua própria Lista de Solicitação de documentos de entrada: DIRPF, Livro Caixa do Produtor Rural, DRE das empresas do grupo, Contratos da Atividade Econômica (parceria, condomínio, arrendamento), Bens e Dívidas da Atividade Rural, Projeção de Resultado (PF e PJ) e Projeção de Investimentos. A OSG coleta essa documentação junto ao cliente e a encaminha ao Fiscal.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-01-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-01'), 'Intermediar comunicação Fiscal x cliente', 'A OSG atua como ponte: repassa dúvidas do cliente ao Fiscal e agenda reuniões específicas. O Fiscal pode contatar o cliente diretamente para validar a área explorada informada na planilha e confirmar o questionário (modelo de exploração atual e fluxo de comercialização).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-01-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-01'), 'Elaborar relatório tributário: regime de exploração, Funrural e cenários', 'O Fiscal elabora o estudo tributário da atividade rural, que define o regime de exploração (terra nua x demais fatores, base do percentual da parceria), avalia a opção de recolhimento do Funrural (sobre a folha de pagamento x sobre a comercialização) e monta os cenários tributários comparativos. É esse estudo que manda o percentual a constar na parceria (tipicamente 20/80).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-01-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-01'), 'Receber relatório do Fiscal e extrair o percentual da parceria', 'O Fiscal devolve o planejamento tributário com o estudo da atividade rural, que define o percentual a constar no contrato de parceria. A OSG recebe o relatório e usa o percentual como insumo para fechar a parceria.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-02-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-02'), 'Identificar arrendamento pré-existente', 'A partir das informações do cliente e dos contratos da atividade econômica em vigência (parceria, condomínio, arrendamento), identifica-se a existência de arrendamento que precisa ser rescindido antes da nova parceria.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-02-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-02'), 'Elaborar contrato de distrato', 'Elabora-se a minuta do distrato do arrendamento para extinguir a relação jurídica anterior e permitir configurar a nova relação via parceria entre as partes.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-02-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-02'), 'Disponibilizar minuta e registrar distrato em cartório', 'Disponibiliza-se a minuta ao cliente para assinatura e orienta-se o registro do distrato em cartório, formalizando a rescisão do arrendamento.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Obter qualificação da Agro registrada na Junta', 'Aguarda-se o registro do contrato social da Agro na Junta Comercial para ter os dados completos da sociedade agropecuária, que constarão no contrato como parceiro-outorgante.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Receber planilha de hectares explorados do cliente', 'O cliente preenche e devolve a planilha com os hectares efetivamente explorados por imóvel, que pode ser diferente da área total da matrícula (reserva legal, área de preservação). Esse dado alimenta o anexo do contrato.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Elaborar minuta do contrato de parceria', 'Elabora-se a minuta do contrato de parceria a partir do modelo Word padrão, qualificando a Agro como outorgante e as PFs como outorgadas. Começa em paralelo aos contratos sociais, já antecipando o percentual da parceria.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Montar anexo a partir da matrícula e dos hectares', 'Copiam-se os limites e confrontações da matrícula para o anexo, trocando o proprietário para a PJ, removendo o valor contábil e adicionando os hectares explorados. Exige conferência caractere por caractere da descrição de área.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Ajustar percentual conforme planejamento tributário', 'Com o planejamento tributário fechado, ajusta-se o percentual da parceria (tipicamente 20/80) no contrato, já que é o estudo tributário que manda o percentual a constar.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e6'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Revisar contrato (assistente, checklist e sênior)', 'O contrato passa pelo fluxo de revisão em três níveis: após a elaboração pelo assistente, segue para conferência por checklist e depois para a revisão do sênior, que aprova internamente antes de liberar a minuta ao cliente. Todo contrato passa por pelo menos três pessoas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-03-e7'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-03'), 'Disponibilizar minuta, colher assinatura e registrar em cartório', 'Disponibiliza-se a minuta ao cliente para análise e assinatura, e orienta-se o registro do contrato em cartório (registro de títulos e documentos), formalizando a parceria.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 8, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-04-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-04'), 'Identificar PFs outorgadas e modalidade de composse', 'Identificam-se as pessoas físicas que figuram como parceiros-outorgados na parceria e define-se a modalidade de composse, na maioria pro indiviso (a divisão por área, pro diviso, é exceção). Verifica-se também se há área arrendada de terceiros que entra na exploração e que precisa ser contemplada na composse.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-04-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-04'), 'Elaborar minuta do contrato de composse', 'Elabora-se a minuta do contrato de composse entre as PFs, regulando a divisão dos 80% e fazendo remissão ao contrato de parceria como instrumento principal. Quando há área arrendada de terceiros que entra na exploração comum, ela é incorporada à composse. Feito em paralelo aos demais contratos.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-04-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-04'), 'Montar anexo da composse (descrição da matrícula + hectares)', 'Monta-se o anexo do contrato de composse com a mesma lógica do anexo da parceria: copiam-se os limites e confrontações da matrícula e adicionam-se os hectares efetivamente explorados. O dado da planilha de hectares alimenta tanto o anexo da parceria quanto o da composse, exigindo a mesma conferência caractere por caractere.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-04-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-04'), 'Revisar contrato de composse (assistente, checklist e sênior)', 'O contrato de composse passa pelo fluxo de revisão em três níveis: elaboração pelo assistente, conferência por checklist e revisão do sênior, que aprova internamente antes de liberar a minuta ao cliente. Todo contrato passa por pelo menos três pessoas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p3-04-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p3-04'), 'Disponibilizar minuta, colher assinatura e registrar em cartório', 'Disponibiliza-se a minuta ao cliente para assinatura e orienta-se o registro do contrato de composse em cartório, formalizando a relação entre as PFs.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-01-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-01'), 'Montar apresentação inicial de sucessão', 'A equipe prepara a apresentação expondo os caminhos sucessórios possíveis (doação em vida x testamento, doação na holding controladora) sem cenários numéricos definidos, a partir do modelo padrão usado em projetos anteriores.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-01-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-01'), 'Apresentar opções de sucessão ao cliente', 'Reunião com o cliente para expor as opções de sucessão (doação x testamento) e introduzir o tema, sem ainda decidir se haverá doação. Serve para o cliente começar a refletir sobre a estrutura sucessória.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-02-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-02'), 'Abrir demanda de cálculo de ITCMD ao Fiscal', 'A OSG abre a demanda para a área Fiscal calcular o ITCMD e disponibiliza ao cliente a planilha padrão de cotas para preenchimento, repassando-a ao Fiscal quando o cliente devolve. A troca da planilha de cotas com o cliente ocorre por e-mail e, no caso dos clientes novos, pelo DocBox (canal pelo qual eles enviam os documentos).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-02-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-02'), 'Calcular legítima e parte disponível', 'Com base no cunho familiar do cliente (quantidade de filhos e herdeiros), a OSG calcula a divisão entre legítima e parte disponível, conforme a legislação, para orientar como a doação das cotas será distribuída.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-02-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-02'), 'Receber e validar cálculo dos 3 cenários de ITCMD', 'A área Fiscal executa o cálculo do ITCMD nos três cenários (valor contábil, valor de ITR e valor de mercado) e devolve o resultado. A OSG recebe e valida o relatório para preparar a apresentação final ao cliente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-03-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-03'), 'Montar apresentação final com cenários de ITCMD', 'A equipe monta a apresentação resumindo o projeto consolidado e demonstrando os cenários de valor estimado de ITCMD (contábil, ITR e mercado), para o cliente ter ciência do custo do recolhimento.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-03-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-03'), 'Apresentar cenários e colher decisão do cliente', 'Reunião específica com o cliente para apresentar os cenários de ITCMD e discutir a definição da doação. O cliente decide se segue com a doação e qual cenário de valor será a base para o recolhimento.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-04-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-04'), 'Orientar cliente sobre recolhimento e emissão de guias', 'Com o cenário escolhido, a PSA orienta o cliente e sua contabilidade a seguir com a emissão das guias de ITCMD; a emissão e o pagamento são de responsabilidade da contabilidade do cliente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-04-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-04'), 'Acompanhar quitação do ITCMD', 'A PSA acompanha junto ao cliente a quitação do imposto, cobrando o status, pois sem a quitação não é possível formalizar a doação na Junta Comercial. Quando o cliente contesta o valor judicialmente, o projeto fica travado.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-05-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-05'), 'Elaborar minuta do instrumento de doação', 'A equipe elabora a minuta da doação das cotas da Participações (fundadores para herdeiros, em partes iguais), a partir do modelo padrão, ajustando cláusulas restritivas e reserva de usufruto conforme a vontade da família.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-05-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-05'), 'Disponibilizar minuta e sanar dúvidas com o cliente', 'A PSA disponibiliza a minuta ao cliente para análise e realiza reuniões para esclarecer dúvidas, especialmente sobre cláusulas (ex.: recebimento em dinheiro x em fazenda no caso de falecimento de sócio).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-05-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-05'), 'Coletar assinatura do instrumento de doação', 'Após a aprovação da minuta e a quitação do ITCMD, o instrumento de doação é assinado eletronicamente via gov.br pelos sócios fundadores (doadores) e pelos herdeiros sucessores (donatários), que são as partes que efetivamente assinam o instrumento. A contabilidade do cliente detém o certificado digital usado no processo, mas não é quem assina a doação. Em alguns projetos essa assinatura só ocorre se o Acordo de Quotistas (P5.02) já estiver assinado.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-06-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-06'), 'Elaborar AC de reflexo da doação', 'A equipe elabora a alteração contratual da Participações referenciando o instrumento de doação, registrando que as cotas do fundador passam ao sucessor, a partir do modelo padrão de AC.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-06-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-06'), 'Coletar assinatura da alteração contratual', 'Após a quitação do ITCMD, a AC é disponibilizada para assinatura eletrônica via gov.br pelas partes (sócios fundadores e sucessores), em conjunto com o instrumento de doação. A contabilidade do cliente detém o certificado digital, mas a autoria da assinatura é dos sócios.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-06-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-06'), 'Registrar AC na Junta Comercial', 'A alteração contratual é protocolada na Junta Comercial para formalizar a nova composição societária pós-doação. Só pode ser feita após a quitação do ITCMD.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-07-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-07'), 'Elaborar minuta do testamento', 'A PSA elabora a minuta do testamento para o cliente que opta por não doar em vida, formalizando a destinação das cotas/patrimônio aos herdeiros.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-07-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-07'), 'Disponibilizar minuta para aprovação do cliente', 'A minuta do testamento é disponibilizada ao cliente para análise e aprovação, com esclarecimento de dúvidas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p4-07-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p4-07'), 'Indicar lavratura do testamento em cartório de notas', 'A PSA leva a minuta ao cartório e indica a lavratura do testamento perante o tabelião; o cartório faz a feitura do documento público, que fica registrado na central.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-01-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-01'), 'Apresentar o projeto de governança ao cliente', 'Apresentação do projeto de governança e da proposta de organização societária ao cliente, abrindo o pilar e alinhando o escopo da profissionalização da gestão familiar (fase do template OpenProject Apresentação do Projeto de Governança).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-01-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-01'), 'Preparar questionário de governança padrão', 'A equipe recupera o rol de perguntas padrão em branco usado para os documentos de governança e o prepara para envio ao cliente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-01-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-01'), 'Realizar reunião de diagnóstico com o cliente', 'Reunião específica com o cliente para trabalhar os pontos de governança familiar (profissionalização da gestão, filhos diretores, regras de entrada de familiares). A reunião costuma ser objetiva porque o questionário também é. O sócio participa por ser quem domina a governança a fundo.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-01-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-01'), 'Coletar e consolidar respostas do cliente', 'Conforme o cliente responde, a equipe preenche e consolida as respostas que servirão de base para o acordo de quotistas, o protocolo de remuneração e a matriz de alçadas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Reunir contrato social e checklist do cliente', 'A equipe reúne o contrato social da empresa-alvo, os contratos das holdings e o checklist/respostas do cliente, que são a fonte de qualificação das partes e das opções de cláusula.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Realizar reunião específica do acordo de quotistas', 'Reunião dedicada com o cliente para definir as regras que entrarão no acordo (preferência, eventos pessoais, saída/exclusão, quóruns). Pode demandar mais de uma reunião até fechar.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Elaborar minuta do acordo a partir do modelo e da biblioteca de cláusulas', 'A equipe parte do modelo-base do escritório (referência canônica Mattei para estrutura e Novafértil para estilo) e da biblioteca de cláusulas, substituindo os campos pelos dados do cliente e escolhendo as variantes indicadas pelo checklist, incluindo as variantes obrigatórias. Itens sem informação ficam marcados como pendentes.', 'hibrido', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Revisar minuta em camadas (NotebookLM)', 'Revisão do acordo em cinco camadas via NotebookLM — estrutura, redação, completude, coerência interna e adequação de variantes — produzindo um sumário executivo por cláusula que aponta pendências e divergências antes de submeter à aprovação.', 'hibrido', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Gerar preview (.md) e obter aprovação do cliente antes do .docx', 'Antes de gerar o documento Word final, gera-se um preview em Markdown (.md) com o conteúdo do acordo e as notas de pendências para o cliente revisar e aprovar. É um gate inviolável: o .docx só é gerado após a aprovação do preview.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e6'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Aprovar e gerar a versão final do acordo', 'Após autorização explícita do sócio responsável, gera-se a versão final em Word. Alterações em modelo-base dependem da aprovação do Cuba.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 7, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-02-e7'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-02'), 'Coletar assinaturas do acordo', 'Colhem-se as assinaturas dos quotistas, intervenientes e testemunhas, física ou digitalmente (com validade via certificado ICP-Brasil quando digital), e o documento assinado é arquivado no Docbox.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 8, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Ler contrato social e extrair qualificação', 'A equipe lê o contrato social do cliente e extrai a qualificação das sócias (holdings ou pessoas físicas), administradores/diretores e dados da empresa operacional.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Realizar reunião específica e preencher planilha checklist', 'Reunião específica para trabalhar os pontos do protocolo: percorre-se a planilha checklist de categorias de benefícios por persona e o cliente estipula as regras de remuneração. O número de personas varia por cliente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Elaborar minuta do protocolo a partir do modelo base', 'A equipe gera a minuta do protocolo a partir do arquivo de referência canônico (Fazenda Bela Vista), preenchendo os campos do cliente e estruturando as cláusulas por persona conforme a planilha. Itens pendentes na planilha são sinalizados, nunca omitidos.', 'hibrido', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Revisar minuta', 'Revisão da minuta antes da geração do documento final: dados ausentes, itens pendentes da planilha, partes que assinarão como anuentes e modalidade de assinatura.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e5'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Gerar preview (.md) e obter aprovação do cliente antes do .docx', 'Antes de gerar o Word final, gera-se um preview em Markdown (.md) com as notas de revisão (pendências, partes anuentes e modalidade de assinatura) para o cliente aprovar. Gate inviolável: o .docx só sai após aprovação do preview.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e6'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Aprovar e gerar versão final do protocolo', 'Após autorização explícita do sócio responsável, gera-se a versão final em Word. Alterações no modelo-base dependem da aprovação do Cuba.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 7, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-03-e7'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-03'), 'Coletar assinaturas do protocolo', 'Colhem-se as assinaturas das partes, das empresas operacionais anuentes e das testemunhas, física ou digitalmente, e o documento assinado é arquivado no Docbox.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 8, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-04-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-04'), 'Realizar reunião específica da matriz de alçadas', 'Reunião dedicada com o cliente para discutir a planilha de matriz de alçadas, definindo limites de atribuição por cargo e os pontos em que a decisão sobe para conselho ou reunião de sócios.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-04-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-04'), 'Mapear alçadas e montar a planilha', 'A equipe mapeia os limites de cada cargo e monta a planilha de matriz de alçadas com quem aprova o que e os valores/limites de cada nível.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-04-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-04'), 'Revisar e aprovar a matriz', 'Revisão da planilha e aprovação com o cliente; a matriz fundamenta o que será levado ao contrato social.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-05-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-05'), 'Confirmar formação do conselho de administração', 'A equipe confirma, conforme o porte e a decisão do cliente, a implantação de um conselho de administração, que é a condição para existir o regimento.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-05-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-05'), 'Elaborar o regimento interno do conselho', 'A equipe redige o regimento interno definindo as regras de funcionamento do conselho de administração. Por não haver questionário padrão, a elaboração é mais específica do que a dos demais documentos.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-05-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-05'), 'Revisar e aprovar o regimento', 'Revisão da minuta e aprovação com o cliente. Alterações no modelo-base dependem da aprovação do Cuba.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-06-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-06'), 'Elaborar alteração contratual refletindo a governança', 'A equipe altera as cláusulas de administração do contrato social da Participações para constar o conselho de administração e a diretoria, incorporando o que foi definido na governança (incluindo a matriz de alçadas).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-06-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-06'), 'Revisar a alteração contratual', 'Revisão da minuta de alteração contratual quanto à redação das cláusulas de administração e coerência com a estrutura de governança definida.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-06-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-06'), 'Aprovar e coletar assinaturas', 'Aprovação final e coleta das assinaturas dos sócios na alteração contratual; o documento assinado é arquivado no Docbox.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p5-06-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p5-06'), 'Registrar alteração na Junta Comercial', 'A alteração contratual é protocolada e registrada na Junta Comercial para formalizar o conselho/diretoria na sociedade.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-01-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-01'), 'Alinhar escopo do projeto com a gerência', 'O líder do projeto alinha com a gerência o escopo do trabalho OSG a ser feito para o cliente, definindo abrangência e objetivos antes de acionar o cliente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-01-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-01'), 'Elaborar memorando de documentos preliminares', 'Monta a lista (memorando) dos documentos preliminares necessários ao projeto (matrículas, declarações de IR, documentos pessoais dos sócios, contratos pré-existentes).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-01-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-01'), 'Solicitar documentos ao cliente', 'Envia o memorando ao cliente solicitando o envio dos documentos preliminares, normalmente por e-mail ou WhatsApp, com os novos clientes enviando os documentos diretamente pelo Docbox.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-01-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-01'), 'Controlar retorno dos documentos do cliente', 'Acompanha o recebimento dos documentos enviados pelo cliente pelo Docbox, e-mail e WhatsApp, faz checklist do que foi entregue e cobra as pendências. A devolutiva do cliente é a principal trava do início do projeto.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-02-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-02'), 'Realizar entrevista preliminar com o cliente', 'Conduz a reunião de kickoff com o cliente para entender o contexto da família e do grupo e abrir o projeto.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-02-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-02'), 'Identificar expectativas do cliente e riscos eminentes', 'Levanta as expectativas do cliente quanto ao projeto e os riscos eminentes (sucessórios, patrimoniais, de governança) que precisam ser tratados.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-02-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-02'), 'Identificar líder do projeto interno e externo', 'Define quem será o líder interno (PSA) e o líder externo (lado do cliente) responsáveis pela interlocução ao longo do projeto.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-02-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-02'), 'Levantar qualificação inicial dos sócios e participação societária', 'Monta um quadro preliminar com a qualificação dos sócios e a eventual participação societária, como leitura inicial para os pilares seguintes. O detalhamento e o WP de qualificação ocorrem depois, em P2.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 6, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-03-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-03'), 'Elaborar o projeto de sucessão empresarial', 'Consolida os diagnósticos em um documento/apresentação de projeto de sucessão empresarial, com a proposta de estrutura societária, patrimonial, agrária, sucessória e de governança para o cliente.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-03-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-03'), 'Submeter o projeto à aprovação do cliente', 'Apresenta o projeto de sucessão empresarial ao cliente e obtém a aprovação formal da proposta, ajustando pontos quando necessário.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-03-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-03'), 'Formalizar contrato com o cliente', 'ETAPA INFERIDA (não consta nos templates do OpenProject): a fase 07 - Formalização do Projeto contém apenas "Elaborar o projeto de sucessão empresarial" e "Submeter o projeto à aprovação do cliente". Esta etapa representa, na prática, a formalização do contrato de prestação de serviço do projeto OSG com o cliente, com assinatura das partes, registrando o go formal do projeto. O papel "Sócio aprovado" também é inferido e não tem respaldo direto nos templates.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-04-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-04'), 'Atualizar status e prazos no OpenProject', 'Mantém as fases e tarefas do projeto atualizadas no OpenProject (datas, status, atribuições), acompanhando o avanço de cada pilar. Seniores e assistentes também acompanham processos no Legal One.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-04-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-04'), 'Realizar reuniões internas de sprint', 'Conduz reuniões internas de acompanhamento (sprint) com a equipe para revisar pendências, distribuir tarefas e orientar a execução dos pilares.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 2, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-04-e3'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-04'), 'Atualizar o cliente sobre o andamento', 'Comunica ao cliente o status do projeto, pendências e próximos passos, geralmente por e-mail/WhatsApp ou reunião de acompanhamento.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 4, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-04-e4'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-04'), 'Cobrar pendências e devolutivas do cliente', 'Acompanha e cobra do cliente os documentos e decisões pendentes que travam o avanço do projeto (devolutiva, recolhimento de tributos, regularizações).', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 5, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-05-e1'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-05'), 'Realizar diagnóstico flash dos objetivos', 'Faz um diagnóstico flash verificando se os objetivos do projeto foram alcançados e se há novos riscos ao cliente após a implementação das estruturas.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 1, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('etp-osg-p6-05-e2'), 'AS-IS', NULL, mapa_uuid('prc-osg-p6-05'), 'Elaborar relatório final do projeto', 'Consolida em relatório final o que foi entregue no projeto (estruturas constituídas, contratos, doações, governança) e as eventuais pendências remanescentes.', 'manual', NULL, NULL, NULL, NULL, NULL, NULL, 3, to_timestamp(1780197035), to_timestamp(1780197035)),
