INSERT INTO public.projects
  (id, name, description, cluster_id, projects_per_year, start_date, end_date, status, area, created_at, updated_at)
VALUES
  (mapa_uuid('prj-osg-p1'), 'P1 - Organização Patrimonial', 'Pilar fundador do OSG. Levanta e consolida todo o patrimônio do cliente em uma planilha-mestra (DP), cruzando matrícula, IR e CCIR/IPTU, e classificando cada bem quanto à integralização. É o controle de todo o projeto: se o DP trava, tudo trava (o societário é rebarba do patrimonial). Cobre o diagnóstico inicial, sua atualização recorrente (gatilho da cascata de alterações contratuais) e a digitação de matrícula com limites e confrontações precisos.', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, NULL, NULL, 'active', 'OSG', to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prj-osg-p2'), 'P2 - Organização Societária', 'Pilar mais volumoso e de maior retrabalho da OSG. Constitui as PJs (Agro operacional que recebe os imóveis; Participações controladora que recebe as cotas da Agro; e holdings individuais quando há) e executa as alterações contratuais que movimentam o patrimônio: integralização dos imóveis na Agro (cláusula 5ª), cessão de cotas das PFs para a Participações (concentração de cotas na controladora) e integralização de imóveis adicionais de 2º momento. Trabalho em modelo Word, com revisão obrigatória por 3 pessoas (assistente -> checklist -> sênior) e registro na Junta Comercial. Absorve a fase OpenProject 10 Organização Societária e Patrimonial.', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, NULL, NULL, 'active', 'OSG', to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prj-osg-p3'), 'P3 - Instrumentos Agrários', 'Regula a exploração rural pós-integralização. Depois que os imóveis viraram da PJ Agro, surge a necessidade de formalizar quem explora a terra (as PFs da família) e em que proporção. Compreende o planejamento tributário rural (executado pela equipe Fiscal, que define o percentual da parceria), o eventual distrato de arrendamento pré-existente, o contrato de parceria rural (PJ Agro outorgante x PFs outorgadas, tipicamente 20/80 com terra nua, Lei 4.504/64) e o contrato de composse entre as PFs (regula os 80%, remete à parceria como instrumento principal). Absorve a fase OpenProject 11 Organização da Atividade Rural.', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, NULL, NULL, 'active', 'OSG', to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prj-osg-p4'), 'P4 - Sucessão', 'Pilar que conclui o projeto OSG. Organiza a transferência do patrimônio consolidado dos fundadores para os herdeiros, evitando inventário futuro. O caminho padrão é a doação de cotas da holding Participações (fundadores para herdeiros em partes iguais), precedida de apresentação inicial de opções, planejamento tributário de ITCMD (executado pela área Fiscal, em 3 cenários), apresentação final com cenários para o cliente decidir, recolhimento do ITCMD pela contabilidade do cliente e alteração contratual refletindo a doação. O testamento é a alternativa quando o cliente opta por não doar em vida.', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, NULL, NULL, 'active', 'OSG', to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prj-osg-p5'), 'P5 - Governança', 'Pilar de governança corporativa e profissionalização da gestão familiar do OSG. Roda em paralelo com a organização societária (P2) e tipicamente fecha junto com o societário no final do projeto. Abre com a apresentação do projeto de governança ao cliente e um questionário de diagnóstico de governança familiar, e desdobra em documentos: acordo de quotistas, protocolo de remuneração, matriz de alçadas e, quando o cliente forma conselho de administração, o regimento interno do conselho e a alteração contratual que reflete o conselho na sociedade. O acompanhamento (follow-up) recorrente da governança é conduzido na gestão do projeto (P6.04). Mudanças em modelos-base passam pela aprovação do Cuba.', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, NULL, NULL, 'active', 'OSG', to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('prj-osg-p6'), 'P6 - Gestão de Projeto OSG', 'Gestão do ciclo de vida do projeto OSG, do kickoff ao handover, conduzida via OpenProject. Reúne as 5 fases canônicas de gestão (01 Solicitações Preliminares, 02 Entrevista Preliminar, 07 Formalização do Projeto, 09 Acompanhamento e Orientação, 14 Finalização do Projeto) que se repetem em quase todo projeto e que hoje são trabalho de coordenação em boa parte invisível no ROI.', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, NULL, NULL, 'active', 'OSG', to_timestamp(1780197035), to_timestamp(1780197035))
