INSERT INTO public.gargalos
  (id, nome, descricao, origem, cluster_id, melhoria_id, horas_gastas, horas_implementacao, taxa_ocorrencia, taxa_captura_apos_melhoria, custo_externo_unico, created_at, updated_at)
VALUES
  (mapa_uuid('gar-osg-p1-01-g1'), 'DP não é revisado', 'O DP é responsabilidade exclusiva de quem o executa e não passa por revisão de outra pessoa, ao contrário dos contratos. A própria equipe reconhece isso como risco estrutural.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-01-g2'), 'Devolutiva do cliente trava o início', 'O envio dos documentos-base pelo cliente (IR, matrículas, CCIR, IPTU, escrituras) é o maior atraso do processo, descrito como o que a equipe chora demais; o trabalho interno espera o cliente.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-01-g3'), 'Leitura manual de matrícula no olhômetro', 'A leitura das averbações é feita inteiramente manual, sem sistema, exigindo ler a matrícula ponta a ponta e até o fim para detectar se um ônus foi posteriormente cancelado. Quem para no meio acha que o imóvel está onerado quando não está mais.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-01-g4'), 'Volume alto de matrículas aumenta risco de confusão', 'Clientes com 50+ imóveis (até ~340) elevam o risco de confusão em número de lote, nome de fazenda e denominação durante a extração e o preenchimento.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-01-g5'), 'Documentos dispersos e padrão de salvamento não seguido', 'Existe manual de cadastro no Docbox, mas nem todos seguem; os DPs e documentos ficam espalhados, sem centralização que dispare tarefa automática quando algo muda.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-01-g6'), 'Bens não declarados no IR', 'Há imóveis com matrícula que não constam no IR; o cliente informa o valor contábil por e-mail e a equipe registra no DP com observação para considerar no próximo exercício.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-01-g7'), 'Matrícula desatualizada (em nome de terceiro/falecido)', 'Quando a matrícula não reflete o proprietário atual, integraliza-se pelos direitos da escritura ou do contrato de compra e venda com remissão à matrícula; o princípio da continuidade impede transferir o que não está em nome do titular.', 'Órgão externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-02-g1'), 'Efeito cascata de alterações contratuais', 'Uma única matrícula nova muda área, valor contábil e denominação, disparando alteração do contrato social e demais artefatos; em estruturas com Agro + Participações + holdings individuais, uma correção pode gerar 5 a 8 alterações contratuais simultâneas.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-02-g2'), 'Coordenação manual da cascata sem rastreamento', 'Não há gatilho automático nem rastreamento de qual imóvel está em qual PJ fora do DP; a atualização e a sinalização dos impactos são manuais, dependendo de a pessoa lembrar de abrir as estruturas afetadas.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-02-g3'), 'Dependência da regularização pelo cliente', 'Imóveis em segundo momento só podem ser atualizados quando o cliente quita o ônus e envia a matrícula regularizada, o que pode demorar e travar a retomada da integralização.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-02-g4'), 'DP atualizado também não é revisado', 'Assim como o inicial, a atualização do DP não passa por revisor; erros propagam diretamente para a cascata de contratos.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-03-g1'), 'Erro em limites e confrontações', 'O cartório confere a descrição caractere por caractere (vírgula por vírgula) na transferência efetiva; um grau que vira um O gera exigência e obriga uma alteração contratual só para corrigir a descrição. É o ponto onde um grau vira um O, risco crítico reconhecido.', 'Órgão externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-03-g2'), 'Transcrição manual da descrição (Ctrl+C / Ctrl+V)', 'Quando não há SIGEF, os limites e confrontações são digitados manualmente do PDF e depois copiados e colados entre documentos, propagando qualquer erro de transcrição para contrato e anexos.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-03-g3'), 'Repasse do DP/digitação para o contrato', 'O assistente que executa o contrato às vezes está muito dentro do projeto e não reabre o DP nem o WP de digitação para conferir, gerando divergências em número de lote, nome de fazenda e denominação entre a matrícula, o DP e o contrato.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p1-03-g4'), 'SIGEF subutilizado', 'O SIGEF pode fornecer a descrição rural de forma estruturada, mas a digitação manual ainda é usada; quando há SIGEF nem sempre alguém o aproveita.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-01-g1'), 'Planilha de capital social no braço e fora do drive compartilhado', 'A planilha de capital social é feita manualmente e não está no drive compartilhado, risco reconhecido pela equipe de perda e de versão única.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-01-g2'), 'Diferença de centavos no capital social', 'Diferenças por casas decimais nas planilhas geram erro no capital social e exposição a questionamento de ITCMD por doação disfarçada quando aporte e cotas não batem.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-01-g3'), 'Devolutiva de documentos do cliente atrasa o início', 'A coleta de documentos pessoais depende do retorno do cliente, descrito pela equipe como o maior atraso do projeto.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-02-g1'), 'Camadas de revisão e troca de caracteres na minuta', 'Dor unânime do time: a minuta passa por múltiplas camadas de revisão e há muita troca de caracteres; a equipe elabora pouco e revisa muito.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-02-g2'), 'Erros recorrentes em campos do contrato', 'Erros recorrentes apontados pelos sêniores: numeração de cláusulas, capital social, formatação, dados pessoais e endereço.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-02-g3'), 'Limites e confrontações conferidos caractere por caractere', 'O cartório confere vírgula por vírgula; um erro de digitação (um grau virando um O) obriga a refazer toda uma alteração contratual.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-02-g4'), 'Discussão de cláusula trava o projeto', 'Quando o cliente quer rediscutir ou entender uma cláusula, é preciso deslocar-se e explicar à família; uma única cláusula pode travar o projeto por meses.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-02-g5'), 'Assinatura via gov.br trava pela agenda do cliente', 'O cliente tem dificuldade com o gov.br e a assinatura depende do certificado digital (que fica com a contabilidade); somado a sócios que viajam, a coleta de assinaturas trava o projeto (relato da reunião de 14/05).', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-02-g6'), 'Alteração de modelo Word exige aprovação do gerente', 'Qualquer mudança no modelo-base do contrato depende de aprovação do gerente e não há versionamento claro.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-03-g1'), 'Camadas de revisão e troca de caracteres na minuta', 'Mesmo padrão de retrabalho da constituição Agro: muita revisão e troca de caracteres na minuta do contrato.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-03-g2'), 'Coordenação do registro simultâneo na Junta', 'Os contratos da Agro e da Participações precisam ser registrados em cadeia no mesmo dia; coordenar essa sequência depende de ambos estarem prontos e assinados.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-03-g3'), 'Assinatura via gov.br trava pela agenda do cliente', 'O cliente tem dificuldade com o gov.br e a assinatura depende do certificado digital (que fica com a contabilidade); somado a sócios que viajam, a coleta de assinaturas trava o projeto (relato da reunião de 14/05).', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-04-g1'), 'Multiplicação de contratos por sócio amplia o retrabalho', 'Cada sócio com holding individual gera mais um contrato a elaborar, revisar e registrar; em estruturas com Agro + Participações + holdings, uma única matrícula nova dispara alterações em cascata em todas as PJs.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-05-g1'), 'Erro em limites e confrontações obriga AC corretiva', 'Como a descrição de área sai da matrícula para a cláusula 5ª e o cartório confere caractere por caractere, qualquer erro de digitação gera nota devolutiva e uma alteração contratual extra só para corrigir a descrição.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-05-g2'), 'Cascata de alterações por matrícula nova', 'Uma única matrícula nova muda área, valor contábil e denominação, disparando 5 a 8 alterações contratuais simultâneas nas PJs da estrutura.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-05-g3'), 'Assistente não reabre o DP para conferir', 'Maior dor interna apontada: o assistente está muito dentro do projeto e não reabre o DP para conferir antes de levar os dados ao contrato.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-05-g4'), 'Assinatura via gov.br trava pela agenda do cliente', 'O cliente tem dificuldade com o gov.br e a assinatura depende do certificado digital (que fica com a contabilidade); somado a sócios que viajam, a coleta de assinaturas trava o projeto (relato da reunião de 14/05).', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-05-g5'), 'Atualização cartorial atrasa pelo custo de ITBI', 'A atualização das matrículas é responsabilidade do cliente e envolve custo de ITBI, levando de 1 a 2 anos no mínimo ou sendo feita imóvel a imóvel.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-06-g1'), 'Cliente confunde cessão de cotas com transferência de matrícula', 'Caso real citado: cliente travou a concentração de cotas por dois meses confundindo a transferência de cotas com transferência de matrícula, mesmo com a minuta pronta.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-06-g2'), 'Dependência de balanço e análise fiscal de lucros', 'Para concluir a concentração de cotas, pode ser necessário que o cliente disponibilize balanço e que a equipe fiscal analise os lucros para decidir se há necessidade de ata, o que pode travar a etapa.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-06-g3'), 'Assinatura via gov.br trava pela agenda do cliente', 'O cliente tem dificuldade com o gov.br e a assinatura depende do certificado digital (que fica com a contabilidade); somado a sócios que viajam, a coleta de assinaturas trava o projeto (relato da reunião de 14/05).', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-06-g4'), 'Registro simultâneo dependente da AC de integralização', 'A cessão precisa ser registrada em cadeia com a integralização da Agro; atraso em uma trava o registro da outra.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-07-g1'), 'Projeto fica suspenso aguardando saneamento da pendência', 'Imóveis de 2º momento ficam aguardando regularização pelo cliente (inventário, ambiental, ônus); o projeto fica suspenso até o cliente avisar e enviar a matrícula atualizada.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-07-g2'), 'Trabalho recorrente após o encerramento do projeto', 'Novas áreas adquiridas ou pendências sanadas anos depois reabrem o DP e geram nova integralização, sobrevivendo ao encerramento oficial do projeto.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-07-g3'), 'Reabertura do DP e recálculo das cotas', 'Cada imóvel novo reabre o DP e exige refazer a contemplação das cotas, gerando retrabalho proporcional.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p2-07-g4'), 'Assinatura via gov.br trava pela agenda do cliente', 'O cliente tem dificuldade com o gov.br e a assinatura depende do certificado digital (que fica com a contabilidade); somado a sócios que viajam, a coleta de assinaturas trava o projeto (relato da reunião de 14/05).', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-01-g1'), 'Comunicação OSG-Fiscal-cliente fragmentada', 'A OSG é a ponte entre cliente e Fiscal; o cliente procura a OSG por ligação ou e-mail, e a OSG precisa ficar avisando o Fiscal (que nem sempre está no mesmo canal). A falta de um canal único gera retrabalho de repasse e atraso de agenda.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-01-g2'), 'Trabalho interno do Fiscal não visível para a OSG', 'O estudo tributário que define o percentual é executado fora da OSG; a OSG depende da devolutiva do Fiscal para fechar a parceria, sem visibilidade do andamento.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-01-g3'), 'Planilha enviada com informação fiscal em vez de gerencial', 'A OSG pede o preenchimento de planilha gerencial, mas o cliente às vezes manda informação com finalidade fiscal; o Fiscal precisa contatar o cliente direto para confirmar a área explorada, gerando idas e vindas.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-02-g1'), 'Caso raro sem fluxo padronizado', 'O distrato só aparece quando o cliente vinha de arrendamento, o que é raro; por não ser recorrente, o trabalho de rescisão não tem um fluxo padronizado e é tratado caso a caso.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-02-g2'), 'Dependência de registro em cartório', 'A formalização da rescisão depende do registro em cartório e da ação do cliente, o que pode atrasar a configuração da nova parceria.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-03-g1'), 'Dependência do registro da Agro na Junta', 'A parceria só pode ser fechada com os dados completos da Agro, que dependem do registro do contrato social na Junta Comercial; até o registro sair, o contrato fica em elaboração mas não finaliza.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-03-g2'), 'Espera pelo planejamento tributário para fechar o percentual', 'Embora a minuta seja elaborada em paralelo, o contrato só fecha depois que o planejamento tributário define o percentual; dependendo do resultado pode mudar a forma ou o instrumento.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-03-g3'), 'Conferência de limites e confrontações copiados da matrícula', 'Os limites e confrontações são copiados da matrícula para o anexo; qualquer erro na descrição de área exige conferência número a número e pode gerar alteração e nota devolutiva.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-03-g4'), 'Descasamento entre área da matrícula e área explorada', 'A área efetivamente explorada (planilha do cliente) costuma diferir da área total da matrícula por reserva legal e área de preservação, exigindo tratamento no anexo.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-03-g5'), 'Risco de parceria de fachada perante a Receita', 'A parceria 20/80 é atraente tributariamente e alvo recorrente da Receita Federal; sem real divisão de risco, pode ser desconsiderada como arrendamento disfarçado.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-03-g6'), 'Revisão da parceria a cada novo imóvel de 2º momento integralizado', 'Todo imóvel adicional integralizado no 2º momento (AC Agro 2º momento) traz nova área a ser explorada e reabre a parceria para rever a área e o percentual, refazendo o anexo. É a mesma cascata de revisão disparada pelos novos imóveis em P1.02/P2.07: uma alteração no DP propaga para o anexo agrário.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-04-g1'), 'Vínculo de dependência com a parceria', 'A composse só faz sentido porque existe a parceria, que é o instrumento principal; depende dela estar definida (partes e percentual) para ser fechada.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-04-g2'), 'Dependência de registro em cartório e assinatura do cliente', 'A formalização depende da assinatura de todas as PFs e do registro em cartório, sujeito à disponibilidade e às dificuldades operacionais do cliente (assinatura via gov.br, agenda).', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p3-04-g3'), 'Bate e volta com o cliente na definição da exploração', 'A composse é uma das etapas com mais discussão com o cliente, pois as PFs precisam definir entre si como vão explorar (especialmente quando entra área arrendada de terceiros), gerando idas e vindas até fechar a minuta.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-01-g1'), 'Indefinição do cliente sobre sucessão', 'Nesta etapa o cliente ainda não decide se fará a doação; a decisão sobre o eixo sucessório costuma se arrastar e é o que mais consome tempo do projeto.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-02-g1'), 'OSG é ponte entre cliente e Fiscal', 'Quando o cliente tem dúvidas tributárias, procura a OSG, que precisa repassar ao Fiscal e agendar reunião específica; o Fiscal nem sempre está no mesmo canal (Slack), exigindo avisos manuais e gerando atraso.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-02-g2'), 'Planilha de cotas com informação inadequada', 'O cliente às vezes preenche a planilha gerencial de cotas com informação de cunho fiscal em vez da realidade gerencial, obrigando a área Fiscal a contatar o cliente diretamente para reconciliar os dados.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-03-g1'), 'Decisão da doação demora', 'A formalização é tranquila, mas a decisão do cliente sobre fazer ou não a doação leva tempo; o patrimônio significativo e o valor do ITCMD pesam na demora.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-04-g1'), 'ITCMD pode travar o projeto indefinidamente', 'Há caso de cliente que fechou o projeto em 2022 e não formalizou a doação porque contesta judicialmente o valor do ITCMD; sem quitação a doação não avança e o projeto permanece pendente por anos.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-04-g2'), 'Dependência da contabilidade do cliente', 'A emissão das guias e o recolhimento ficam com a contabilidade do cliente, fora do controle da PSA, que só acompanha e cobra status.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-05-g1'), 'Discussão de cláusula trava a agenda', 'Uma única cláusula (ex.: sócio recebe em dinheiro e não em fazenda em caso de falecimento) pode obrigar a PSA a se deslocar, explicar ao cliente e à família, travando o projeto por meses por questão de agenda e entendimento.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-05-g2'), 'Elaboramos pouco, mas revisamos muito', 'A minuta de doação parte de um modelo padrão (pouca elaboração nova), mas o esforço se concentra em revisar muito o instrumento a cada ajuste de cláusula e devolutiva do cliente, gerando ciclos de retrabalho que consomem o tempo da equipe.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-05-g3'), 'Dificuldade do cliente com assinatura eletrônica', 'Clientes têm dificuldade com o gov.br para assinar; um sócio viaja, depois outro, e os documentos liberados para assinatura ficam parados, travando o projeto.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-06-g1'), 'Elaboramos pouco, mas revisamos muito', 'A AC de reflexo da doação parte de um modelo padrão (pouca elaboração nova), mas exige revisão intensa para garantir a remissão correta ao instrumento de doação e à composição societária, gerando ciclos de revisão e retrabalho que pesam mais que a redação inicial.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-06-g2'), 'Formalização depende da quitação do ITCMD', 'A AC só pode ser registrada na Junta após a quitação do ITCMD; enquanto o imposto não é pago (ou está em discussão judicial), a doação não se completa na estrutura.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p4-07-g1'), 'Fluxo cartorial fora do controle da PSA', 'A lavratura do testamento depende do cartório de notas e da agenda do cliente, fora do controle direto da PSA, que apenas indica e acompanha.', 'Orgão externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-01-g1'), 'Dependência da devolutiva do cliente', 'A elaboração depende das respostas do cliente; a devolutiva lenta é o maior atraso reconhecido pela equipe e pode travar o avanço da governança.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-01-g2'), 'Governança conhecida por poucos no time', 'A parte de governança é dominada por poucas pessoas (apontada como a única que o Cuba conhece a fundo), concentrando o conhecimento e limitando a padronização do diagnóstico.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-02-g1'), 'Documento menos padronizado com variantes obrigatórias', 'O acordo de quotistas é menos padronizado que os contratos societários; a redação a partir de modelo e biblioteca exige selecionar e adaptar cláusulas manualmente, incluindo a estrutura temática fixa (quotas, eventos pessoais, saída, não concorrência, governança e gerais) e as variantes obrigatórias a partir de 2025 (5-D, 19-B, 20-B, 20-C).', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-02-g2'), 'Referência ainda usa apresentação antiga', 'A base de governança ainda se apoia em apresentação de 2022, embora a estrutura permaneça praticamente a mesma.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-02-g3'), 'Acordo pode travar a doação', 'Em alguns projetos a doação do P4 só ocorre se o acordo for assinado; se o cliente não fecha o acordo, o final do projeto fica vinculado e pode emperrar.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-02-g4'), 'Aprovação de mudança de modelo concentrada no Cuba', 'Qualquer alteração no modelo-base depende da aprovação do Cuba, criando ponto único de aprovação.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-03-g1'), 'Personas variam por cliente', 'O número e tipo de personas (diretores, sucessores, gestores familiares) muda por cliente; é preciso ler a planilha de cada engajamento e não assumir um padrão fixo, exigindo conferência manual.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-03-g2'), 'Ausência de regra padrão de remuneração', 'Não há uma regra fixa de remuneração; o cliente estipula conforme mercado ou percepção, o que torna o documento dependente de definição caso a caso.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-03-g3'), 'Itens pendentes na planilha', 'Itens marcados como pendente ou a definir na planilha precisam ser sinalizados e redigidos como ponto de partida, gerando idas e vindas até a definição do cliente.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-04-g1'), 'Matriz de alçadas gera retrabalho no contrato', 'Colocar a matriz de alçadas no contrato social demanda tempo e é apontada como alteração que gera impacto e retrabalho na fase de alterações contratuais.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-05-g1'), 'Sem questionário padrão', 'O regimento é o único documento de governança sem rol de perguntas padrão em branco, exigindo elaboração mais artesanal caso a caso.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-05-g2'), 'Aplicável só a parte dos clientes', 'Depende do porte do cliente e da decisão de formar conselho; nem todo projeto chega a este documento, o que limita a padronização.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-06-g1'), 'Reescrita de muitas cláusulas', 'Quando o contrato social vem do próprio cliente, é preciso alterar todo o documento para o modelo de cláusula da PSA; em algumas juntas comerciais é necessário especificar cláusula a cláusula (mais de vinte cláusulas), gerando trabalho extenso.', 'Orgao externo', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p5-06-g2'), 'Acoplamento entre governança e societário', 'Formar conselho obriga a revisitar e alterar o contrato social, acoplando a governança à fase societária e ampliando o retrabalho no final do projeto.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-01-g1'), 'Devolutiva do cliente atrasa o início', 'O retorno do cliente com os documentos solicitados é o maior atraso do projeto, descrito pelo time como o que mais se sofre. Sem os documentos, o projeto não avança.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-01-g2'), 'Solicitação informal sem rastreio', 'O pedido de documentos hoje é feito de forma informal por e-mail/WhatsApp, sem um controle estruturado do que falta retornar. Os documentos chegam por múltiplos canais (Docbox, e-mail, WhatsApp, Drive).', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-02-g1'), 'Visibilidade limitada de riscos no início', 'A leitura de expectativas e riscos eminentes depende fortemente da entrevista; pontos relevantes podem só aparecer mais tarde no projeto, gerando retrabalho nos pilares.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-03-g1'), 'Aprovação do cliente pode atrasar o go', 'A submissão do projeto depende da decisão do cliente para aprovar a proposta; enquanto não há aprovação, o projeto fica parado no diagnóstico.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-04-g1'), 'Overhead de gestão invisível no ROI', 'O acompanhamento recorrente consome tempo significativo de coordenação que historicamente não era medido, sendo um dos maiores custos escondidos do projeto.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-04-g2'), 'Falta de visibilidade do andamento', 'Sócios e seniores citam dificuldade de enxergar de forma consolidada o status e os prazos dos projetos em curso. Cada um acompanha por uma mistura de planilha, Slack, agenda, OpenProject e Legal One, e ninguém tem visão completa.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-04-g3'), 'Fragmentação de canais de comunicação', 'Dor mais citada pelos sócios: a comunicação acontece por vários canais sem plataforma única (Slack vs Teams vs Google Chat vs Email/WhatsApp), com ausência de uma plataforma única para abertura de demandas. Ambos os sócios pedem um aplicativo único integrador.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-04-g4'), 'Lançamento de horas desacoplado', 'O lançamento de horas é feito em planilhas separadas dos projetos, sem integração entre o OpenProject (gestão de projetos) e o sistema de horas (Timesheet/Kairós). Cinco pessoas da equipe pediram explicitamente essa integração; como a prioridade são as entregas ao cliente, o lançamento de horas fica atrasado, reforçando o overhead de gestão invisível no ROI.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-04-g5'), 'Projeto pode travar por pendência do cliente', 'O andamento depende de devolutivas, decisões e recolhimentos do cliente, que podem travar o projeto indefinidamente.', 'Cliente', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035)),
  (mapa_uuid('gar-osg-p6-05-g1'), 'Encerramento depende de pendências dos pilares', 'A finalização só se completa quando pendências dos pilares (recolhimento de ITCMD, regularizações cartorárias, alterações em cascata) estão resolvidas, podendo arrastar o fechamento.', 'Interno', '0523512c-f980-4236-8a7c-53e06c9c7a80', NULL, 0, 0, 0, 0, 0, to_timestamp(1780197035), to_timestamp(1780197035))
